        function ClearNoKnownAllergyRowV2(AllergyId) {
            var List = $filter("filter")($scope.obj.AllergyItems, { "AllergyId": AllergyId }, true) || [];
            angular.forEach(List, function (item) {
                if (item.PatientDetailId === 0) {
                    var indexToRemove = $scope.obj.AllergyItems.indexOf(item);
                    if (indexToRemove !== -1) {
                        $scope.obj.AllergyItems.splice(indexToRemove, 1);
                    }
                } else {
                    item.DeleteInd = 'Y';
                }
            });
        }

