        $scope.GetMasterBirthHistory = function (val, type) {
            var params = {
                "ParentOrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "OrganizationId": $scope.HospitalId,
                "UserId": doctorinfo.doctorid,
                "NotesTypeId": 1,
                "HistoryId": 0,
                "PageSize": 10,
                "PageNumber": 1,
                "SearchText": val,
                "Type": '',
                "IsFrequent": "N"
            };
            if (params.SearchText == "") {
                params.IsFrequent = "Y";
            }

            return eHnoteSettingsDataService.GetMasterBirthHistory(params).then(function (resp) {
                if (resp.data.count !== 0) {
                    if (resp.data.BirthHistory !== undefined) {
                        $scope.ROSHistoriesObj.AddBirthHistory = false;
                        return resp.data.BirthHistory.map(function (item) {
                            return item;
                        });
                    } else {
                        $scope.ROSHistoriesObj.AddBirthHistory = true;
                    }
                } else {
                    $scope.ROSHistoriesObj.AddBirthHistory = false;
                    if (val != '') {
                        $scope.ROSHistoriesObj.AddBirthHistory = true;
                    }
                }
            });
        };
        $scope.OnRosBirthHistoryBlurChange = function (birthHistory) {
            if (birthHistory.HistoryId === '') {
                birthHistory.HistoryName = '';
                $scope.obj.SelectedBirthHistoryItem = '';
                return false;
            }
            $scope.obj.SelectedBirthHistoryItem = birthHistory;
            var i = 0;
            $scope.obj.SelectedBirthHistoryItem = $scope.obj.SelectedBirthHistoryItem || "";
            if ($scope.obj.SelectedBirthHistoryItem === "") {
                return;
            }

            $scope.obj.SelectedBirthItemEye = parseInt($scope.obj.SelectedBirthItemEye);
            if (angular.isObject($scope.obj.SelectedBirthHistoryItem)) {
                var object = {
                    "PatientDetailId": 0,
                    "HistoryId": $scope.obj.SelectedBirthHistoryItem.HistoryId,
                    "HistoryName": $scope.obj.SelectedBirthHistoryItem.HistoryName,
                    "IsEdit": true,
                    "showBirthHistory": false,
                    "ActiveInd": true,
                    "DeleteInd": 'N',
                    "Remarks": $scope.obj.SelectedBirthHistoryItem.Remarks || "",
                    "OrganId": $scope.obj.SelectedBirthItemEye,

                    "Duration": $scope.obj.SelectedBirthHistoryItem.Duration || "",
                    "DurationType": $scope.obj.SelectedBirthHistoryItem.DurationType || "D",
                    "DurationDate": null,
                    "ShowDateFormat": true,
                    "ShowNote": false,
                    "IsFrequent": $scope.obj.SelectedBirthHistoryItem.IsFrequent || "",
                };
            } else {
                var object = {
                    "PatientDetailId": 0,
                    "HistoryId": 0,
                    "HistoryName": $scope.obj.SelectedBirthHistoryItem,
                    "IsEdit": true,
                    "showBirthHistory": false,
                    "ActiveInd": true,
                    "DeleteInd": 'N',
                    "Remarks": $scope.obj.SelectedBirthHistoryItem.Remarks || "",
                    "OrganId": $scope.obj.SelectedBirthItemEye,

                    "Duration": $scope.obj.SelectedBirthHistoryItem.Duration || "",
                    "DurationType": $scope.obj.SelectedBirthHistoryItem.DurationType || "D",
                    "DurationDate": null,
                    "ShowDateFormat": true,
                    "ShowNote": false,
                    "IsFrequent": $scope.obj.SelectedBirthHistoryItem.IsFrequent || "",
                };
            }



            var i = 0;
            if ($scope.obj.BirthHistory.length > 0) {
                angular.forEach($scope.obj.BirthHistory, function (item) {
                    if (item.HistoryId === $scope.obj.SelectedBirthHistoryItem.HistoryId && item.DeleteInd == 'N') {
                        alertify.error('You have already entered this Birth history');
                        $scope.obj.SelectedBirthHistoryItem = "";
                        i++;
                    }
                });
            }
            if ($scope.obj.BirthHistory.length !== 0) {
                var List = $filter("filter")($scope.obj.BirthHistory, { "HistoryId": 1 }, true);
                if (List.length > 0) {
                    angular.forEach(List, function (item) {
                        if (item.PatientDetailId === 0) {
                            var indexToRemove = $scope.obj.BirthHistory.indexOf(item);
                            if (indexToRemove !== -1) {
                                $scope.obj.BirthHistory.splice(indexToRemove, 1);
                            }
                        }
                        else {
                            item.DeleteInd = 'Y';
                        }
                    });
                }
                $scope.obj.isNKBHSelected = false
                angular.forEach($scope.obj.BirthHistory, function (item) {
                    item.IsEdit = false;
                });
            }
            if (i == 0) {
                var FreqList = $filter("filter")($scope.FrequentlyBirthHistory, function (fitem) {
                    return fitem.HistoryId == $scope.obj.SelectedBirthHistoryItem.HistoryId;
                }, true) || [];
                if (FreqList.length > 0) {
                    FreqList[0].Onselect = true;
                }
                object.GeneralPatientHistoryId = 0;
                $scope.obj.BirthHistory.unshift(object);
            }
 
            $scope.obj.SelectedBirthHistoryItem = "";
        };
