                   // if (itemA.ReactionName) newLine += `, Allergy Reaction: ${itemA.ReactionName}`;

                    //if (itemA.AllergyTypeId) {
                    //    let tempArray = $filter('filter')($scope.ROSAllergyType, { 'ROSAllergyTypeId': itemA.AllergyTypeId }, true);
