        $scope.compareCurrentEyeMedications = function (CurrentEyeMedications, RefillsArray, QuantityUnitArray) {

            let getRefillName = id => ($filter("filter")(RefillsArray, { MedicineDosaageFieldId: id || 0 }, true)[0] || {}).Description || "";
            let getQuantityUnitName = id => ($filter("filter")(QuantityUnitArray, { MedicineDosaageFieldId: id || 0 }, true)[0] || {}).Description || "";
            CurrentEyeMedications = CurrentEyeMedications || [];
            $scope.LogObj.CurrentEyeMedications = $scope.LogObj.CurrentEyeMedications || [];
            const userOldCurrentEyeMedications = $filter("filter")($scope.LogObj.CurrentEyeMedications, { "CreatedBy": $scope.UserId }, true) || [];

            let editedItems = [];
            let deletedItems = [];

            angular.forEach(CurrentEyeMedications, function (item) {
                item.Sig = item.Sig || '';
                item.StartDate = item.StartDate ? $filter('date')(item.StartDate, 'MM-dd-yyyy') : null;
                item.StopDate = item.StartDate ? $filter('date')(item.StopDate, 'MM-dd-yyyy') : null;

                if (item.DeleteInd === 'Y') {
                    let delDesc = item.MedicineName;
                    //if (item.Sig !== '') delDesc += ' Sig:' + item.Sig;
                    //if (item.StartDate) delDesc += ' StartDate:' + item.StartDate;
                    deletedItems.push(delDesc);
                } else {
                    // Try to find a matching item from previous saved log
                    const normalizeDate = (date) => date ? $filter('date')(new Date(date), 'MM-dd-yyyy') : '';
                    const normalizeBool = (val) => (val || '').toString().toLowerCase();
                    const normalizeNum = (val) => val ? parseInt(val, 10) : 0;

                    const matched = $scope.LogObj.CurrentEyeMedications.some(function (oldItem) {
                        oldItem.Sig = oldItem.Sig || '';
                        oldItem.StartDate = oldItem.StartDate ? $filter('date')(oldItem.StartDate, 'MM-dd-yyyy') : null;
                        oldItem.StopDate = oldItem.StartDate ? $filter('date')(oldItem.StopDate, 'MM-dd-yyyy') : null;

                        return (

                            normalizeNum(oldItem.MedicineId) === normalizeNum(item.MedicineId) &&
                            normalizeNum(oldItem.ActionId) === normalizeNum(item.ActionId) &&
                            normalizeNum(oldItem.DaysSupplyId) === normalizeNum(item.DaysSupplyId) &&
                            normalizeNum(oldItem.DoseId) === normalizeNum(item.DoseId) &&
                            normalizeNum(oldItem.DoseOtherId) === normalizeNum(item.DoseOtherId) &&
                            normalizeNum(oldItem.FrequencyId) === normalizeNum(item.FrequencyId) &&
                            normalizeNum(oldItem.RouteId) === normalizeNum(item.RouteId) &&
                            normalizeDate(oldItem.StartDate) === normalizeDate(item.StartDate) &&
                            normalizeDate(oldItem.StopDate) === normalizeDate(item.StopDate) &&
                            (oldItem.Sig || '') === (item.Sig || '') &&
                            normalizeNum(oldItem.RefillId) === normalizeNum(item.RefillId) &&
                            normalizeNum(oldItem.Quantity) === normalizeNum(item.Quantity) &&
                            normalizeNum(oldItem.QuantityUnitId) === normalizeNum(item.QuantityUnitId) &&
                            normalizeNum(oldItem.StopReasonId) === normalizeNum(item.StopReasonId) &&
                            normalizeBool(oldItem.SubstitutionPermitted) === normalizeBool(item.SubstitutionPermitted) &&
                            (oldItem.PatientInstructions || '') === (item.PatientInstructions || '')

                            //oldItem.MedicineId === item.MedicineId &&
                            //oldItem.ActionId === item.ActionId &&
                            //oldItem.DaysSupplyId === item.DaysSupplyId &&
                            //oldItem.DoseId === item.DoseId &&
                            //oldItem.DoseOtherId === item.DoseOtherId &&
                            //oldItem.FrequencyId === item.FrequencyId &&
                            //oldItem.RouteId === item.RouteId &&
                            //oldItem.StartDate === item.StartDate &&
                            //oldItem.Sig === item.Sig &&
                            //oldItem.RefillId === item.RefillId &&
                            //oldItem.Quantity === item.Quantity &&
                            //oldItem.QuantityUnitId === item.QuantityUnitId &&
                            //oldItem.SubstitutionPermitted === item.SubstitutionPermitted &&
                            //(oldItem.PatientInstructions || '') === (item.PatientInstructions || '')
                        );
                    });

                    if (!matched) {
                        item.Sig = item.Sig||'';
                        item.StopDate = item.StartDate ? $filter('date')(item.StopDate, 'MM-dd-yyyy') : null;
                        item.StartDate = item.StartDate ? $filter('date')(item.StartDate, 'MM-dd-yyyy') : null;
                        let newText = `${item.MedicineName}`;
                        if (item.Sig && item.Sig.trim() !== "") newText += ' Sig:' + item.Sig;
                        if (item.StartDate) newText += ' StartDate:' + item.StartDate;
                        if (item.RefillId) newText += ' Refill:' + getRefillName(item.RefillId);
                        if (item.Quantity) newText += ' Quantity:' + item.Quantity;
                        if (item.QuantityUnitId) newText += ' Quantity Unit:' + getQuantityUnitName(item.QuantityUnitId);
                        if (item.MedicineId != 1) {
                        if (item.SubstitutionPermitted !== undefined) {
                            let subNew = item.SubstitutionPermitted === "y" ? "Yes" : "No";
                            newText += ' Substitution:' + subNew;
                        }
                        }
                        if (item.StopDate) newText += ' StopDate:' + item.StopDate;
                        if (item.StopReasonId) newText += ' Reason:' + item.StopReason;
                        if (item.PatientInstructions) newText += ' Instructions:' + item.PatientInstructions;
                        editedItems.push({
                            newText: newText,
                            medicineId: item.MedicineId
                        });
                    }
                }
            });

            // Add Edited log
            if (editedItems.length > 0) {
                let newDesc = 'Current Eye Medication - ' + editedItems.map(i => i.newText).join(', ');

                let oldDescItems = $scope.LogObj.CurrentEyeMedications
                    .filter(oldItem => editedItems.some(e => e.medicineId === oldItem.MedicineId))
                    .map(oldItem => {
                        oldItem.Sig = oldItem.Sig || '';
                        oldItem.StartDate = oldItem.StartDate ? $filter('date')(oldItem.StartDate, 'MM-dd-yyyy') : null;
                        oldItem.StopDate = oldItem.StopDate ? $filter('date')(oldItem.StopDate, 'MM-dd-yyyy') : null;
                        let info = oldItem.MedicineName;
                        if (oldItem.Sig && oldItem.Sig.trim() !== "") info += ' Sig:' + oldItem.Sig;
                        if (oldItem.StartDate) info += ' StartDate:' + oldItem.StartDate;
                        if (oldItem.RefillId) info += ' Refill:' + getRefillName(oldItem.RefillId);
                        if (oldItem.Quantity) info += ' Quantity:' + oldItem.Quantity;
                        if (oldItem.QuantityUnitId) info += ' Quantity Unit:' + getQuantityUnitName(oldItem.QuantityUnitId);
                        if (oldItem.MedicineId != 1) {
                        if (oldItem.SubstitutionPermitted !== undefined) {
                            let subOld = oldItem.SubstitutionPermitted === "y" ? "Yes" : "No";
                            info += ' Substitution:' + subOld;
                        }
                        }
                        if (oldItem.StopDate) info += ' StopDate:' + oldItem.StopDate;
                        if (oldItem.StopReasonId) info += ' Reason:' + oldItem.StopReason;
                        if (oldItem.PatientInstructions) info += ' Instructions:' + oldItem.PatientInstructions;
                        return info;
                    });

                let oldDesc = oldDescItems.length > 0
                    ? 'Current Eye Medication - ' + oldDescItems.join(', ')
                    : '';
                let actionType = 'Edited';
                if (userOldCurrentEyeMedications.length === 0 && oldDesc === '') {
                    actionType = 'Added';
                }
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 48,
                    SubModuleName: "ROS",
                    ScreenType: "ROS(Current Eye Medication)",
                    ActionType: actionType,
                    OldActionDescription: oldDesc,
                    NewActionDescription: newDesc,
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                });
            }

            // Add Deleted log
            if (deletedItems.length > 0) {
                let delDesc = 'Current Eye Medication - ' + deletedItems.map(i => i).join(', ');
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 2,
                    ModuleName: "ASC",
                    SubModuleId: 3,
                    SubModuleName: "ROS",
                    ScreenType: "Quick Access ROS(Current Eye Medication)",
                    ActionType: "Deleted",
                    OldActionDescription: delDesc,
                    NewActionDescription: '',
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                });
            }
        };

