        $scope.compareVaccinationHistory = function (Addedsystmic) {
            Addedsystmic = Addedsystmic || [];
            $scope.LogObj.VaccinationHistory = $scope.LogObj.VaccinationHistory || [];
            const userOldSystemicHistory = $filter("filter")($scope.LogObj.VaccinationHistory, { "CreatedBy": $scope.UserId }, true) || [];

            let count = 0;
            let dltcount = 0;
            let dltallergyNames = '';
            let DifferenceItem = [];

            angular.forEach(Addedsystmic, function (item) {
                item.AdministeredDate = $filter('date')(item.AdministeredDate, 'MM-dd-yyyy') || null;
               // item.SeverityId = item.SeverityId || null;
                if (item.DeleteInd === 'Y') {
                    if (dltcount > 0) dltallergyNames += ', ';
                    dltallergyNames += item.HistoryName;
                    dltcount++;
                } else {
                    let edited = $scope.LogObj.VaccinationHistory.filter(function (eitem) {
                        eitem.AdministeredDate = $filter('date')(eitem.AdministeredDate, 'MM-dd-yyyy') || null;
                        //eitem.SeverityId = eitem.SeverityId || null;
                        eitem.Duration = eitem.Duration || '';
                        return (
                            eitem.HistoryId == item.HistoryId &&
                            // eitem.SeverityId == item.SeverityId &&
                            eitem.StatusId == item.StatusId &&
                            eitem.Remarks === item.Remarks &&
                            eitem.AdministeredDate == item.AdministeredDate&&
                            eitem.AdministeredStartTime == item.AdministeredStartTime&&
                            eitem.Dosage == item.Dosage&&
                            eitem.UnitName == item.UnitName&&
                            eitem.Manufacturer == item.Manufacturer&&
                            eitem.ManufactureCVX == item.ManufactureCVX
                        );
                    });

                    if (edited.length === 0) {
                        DifferenceItem.push(item);
                        count++;
                    }
                }
            });

            // Edited log
            if (count > 0) {
                let Affecteditem = '';
                let OldAffecteditem = '';
                if (count > 0) {
                    angular.forEach(DifferenceItem, function (itemA) {
                        let newLine = `Vaccination History - ${itemA.HistoryName}`;
                        if (itemA.AdministeredDate) newLine += `, Onset: ${itemA.AdministeredDate}`;
                        if (itemA.AdministeredStartTime) newLine += ` ${itemA.AdministeredStartTime}`;

                        if (itemA.Dosage && itemA.UnitName) {
                            newLine += `, Dosage: ${itemA.Dosage}${itemA.UnitName}`;
                        } else if (itemA.Dosage) {
                            newLine += `, Dosage: ${itemA.Dosage}`;
                        }
                        if (itemA.Manufacturer) newLine += `, Manufacturer: ${itemA.Manufacturer}`;
                        if (itemA.ManufactureCVX) newLine += `, ManufactureCVX: ${itemA.ManufactureCVX}`;

                        if (itemA.StatusId) {
                            let tempArray = $filter('filter')($scope.ROSVaccinationStatus, { 'VaccinationStatusID': itemA.StatusId }, true);
                            if (tempArray.length > 0) {
                                newLine += `, Status: ${tempArray[0].VaccinationStatus}`;
                            }
                        }
                        if (itemA.Remarks) newLine += `, Notes: ${itemA.Remarks}`;

                        Affecteditem += `\n${newLine}`;

                        let matchedOld = $scope.LogObj.VaccinationHistory.find(itemB => itemB.HistoryId === itemA.HistoryId);
                        if (matchedOld) {
                            let oldLine = `Vaccination History - ${matchedOld.HistoryName}`;
                            if (matchedOld.AdministeredDate) oldLine += `, Onset: ${matchedOld.AdministeredDate}`;
                            if (matchedOld.AdministeredStartTime) oldLine += ` ${matchedOld.AdministeredStartTime}`;

                            if (matchedOld.Dosage && matchedOld.UnitName) {
                                oldLine += `, Dosage: ${matchedOld.Dosage}${matchedOld.UnitName}`;
                            } else if (itemA.Dosage) {
                                oldLine += `, Dosage: ${matchedOld.Dosage}`;
                            }
                            if (matchedOld.Manufacturer) oldLine += `, Manufacturer: ${matchedOld.Manufacturer}`;
                            if (matchedOld.ManufactureCVX) oldLine += `, ManufactureCVX: ${matchedOld.ManufactureCVX}`;

                            if (matchedOld.StatusId) {
                                let tempArray = $filter('filter')($scope.ROSVaccinationStatus, { 'VaccinationStatusID': matchedOld.StatusId }, true);
                                if (tempArray.length > 0) {
                                    oldLine += `, Status: ${tempArray[0].VaccinationStatus}`;
                                }
                            }
                            if (matchedOld.Remarks) oldLine += `, Notes: ${matchedOld.Remarks}`;

                            OldAffecteditem += `\n${oldLine}`;
                        }


                    });
                }

                let actionType = 'Edited';
                if (userOldSystemicHistory.length === 0 && OldAffecteditem === '') {
                    actionType = 'Added';
                }
                if (count != 0) {
                    let obj = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 48,
                        "SubModuleName": "ROS",
                        "ScreenType": "ROS(Vaccination History)",
                        "ActionType": actionType,
                        "OldActionDescription": OldAffecteditem.trim(),
                        "NewActionDescription": Affecteditem.trim(),
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                    };
                    $scope.LogObj.LogArray.push(obj);
                }
            }

            if (dltcount != 0) {
                let description = (dltcount === 1)
                    ? `Vaccination History - ${dltallergyNames}`
                    : `Vaccination History - ${dltallergyNames}`;

                let obj = {
                    "LogId": 0,
                    "ModuleId": 1,
                    "ModuleName": "OUTPatient",
                    "SubModuleId": 48,
                    "SubModuleName": "ROS",
                    "ScreenType": "ROS(Vaccination History)",
                    "ActionType": "Deleted",
                    "OldActionDescription": description,
                    "NewActionDescription": '',
                    "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                };
                $scope.LogObj.LogArray.push(obj);
            }

        }
