                if (Allergobj.ImplementedFallRiskProtocol != $scope.LogObj.ImplementedFallRiskProtocol) {
                    if ($scope.LogObj.ImplementedFallRiskProtocol)OldAffecteditem += "\nImplenented High Risk Fall Prevention Interventions: " + ($scope.LogObj.ImplementedFallRiskProtocol ? "true" : "false");
                    if (Allergobj.ImplementedFallRiskProtocol)Affecteditem += "\nImplenented High Risk Fall Prevention Interventions: " + (Allergobj.ImplementedFallRiskProtocol ? "true" : "false");
                }

                //if (Allergobj.NurseFallRiskID != $scope.LogObj.NurseFallRiskID) {
                //    var ReviewedByArraylist = $filter("filter")($scope.allUserList, function (item) { return item.DoctorID == Allergobj.NurseFallRiskID });
