                //            (ReviewedByArraylist[0].LicenseNumber ? " Lic:" + angular.copy(ReviewedByArraylist[0].LicenseNumber) : "");
                //    }
                //    Affecteditem += `\nFall Risk Assessment Reviewed by :${givenByUser} In  Pre-Op Nurse.`;


                //    var ReviewedByArraylist1 = $filter("filter")($scope.allUserList, function (item) { return item.DoctorID == $scope.LogObj.NurseFallRiskID });
                //    if (ReviewedByArraylist1.length > 0) {
                //        givenByUser1 = angular.copy(ReviewedByArraylist1[0].SecondUserFullName) +
                //            (ReviewedByArraylist1[0].LicenseNumber ? " Lic:" + angular.copy(ReviewedByArraylist1[0].LicenseNumber) : "");
