                Affecteditem += "\nImplenented High Risk Fall Prevention Interventions: " + (Allergobj.ImplementedFallRiskProtocol ? "true" : "false");

                //if (Allergobj.NurseFallRiskID != 0) {

                //    var ReviewedByArraylist = $filter("filter")($scope.allUserList, function (item) { return item.DoctorID == Allergobj.NurseFallRiskID });
                //    if (ReviewedByArraylist.length > 0) {
