        $scope.AddNewVaccinationHistory = function (SelectedVaccinationHistory) {
            SelectedVaccinationHistory = SelectedVaccinationHistory || "";
            if (SelectedVaccinationHistory === "") {
                alertify.error("Enter Vaccination History");
                return;
            }
            var object = {
                "ParentOrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "OrganizationId": $scope.HospitalId,
     
                "UserId": $scope.UserId,
                "DeleteInd": false,
                "HistoryName": SelectedVaccinationHistory,
                "HistoryId": 0
            };
            eHnoteSettingsDataService.AddUpdateMasterVaccinationHistory(object).success(function (response) {
                if (response.Status === 'Success') {
                    if (response.count > 0) {
                        $scope.SelectedVaccinationHistory = "";
                        SelectedVaccinationHistory = "";
                        $scope.onRosVaccinationHistoryBlurChange(response.VaccinationHistory[0]);
                        $scope.ROSHistoriesObj.AddVaccinationHistory = false;
                        alertify.success("Successfully Added");
                    }
                }
                if (response.Status === 'Failure') {
                    alertify.error(response.Message);
                    $scope.SelectedVaccinationHistory = "";
                    SelectedVaccinationHistory = "";
                }
            })
                .error(function (error) {
                    alertify.error("Error Occured");
                });
        };
