        $scope.ChangeDrugItemselect = function (item, checked) {
         
            var drugObj = $scope.obj.LifestyleHistoryArray.find(function (historyItem) {
                return historyItem.HistoryId === 3 && historyItem.DeleteInd == 'N';
            });
        
            if (checked) {
              
                if (drugObj.DrugArray.length > 0) {
                    var statusfilter = $filter("filter")(drugObj.DrugArray, { "HistoryHabitsId": item.HistoryHabitsID }, true) || [];
                    if (statusfilter.length > 0) {
                      
                        angular.forEach(drugObj.DrugArray, function (ditem) {
                            if (item.HistoryHabitsID == ditem.HistoryHabitsId) {
                                ditem.ActiveInd = "Y";
                            }
                        });
                    } else {
                       
                        var newObj = {
                            "DrugHistoryId": 0, 
                            "ActiveInd": "Y",
                            "HabitsDescription": item.HabitsDescription,
                            "HistoryHabitsId": item.HistoryHabitsID,
                            "HabitsId": item.HabitsId
                        };
                        drugObj.DrugArray.push(newObj); 
                    }
                } else {
                   
                    var newObj = {
                        "DrugHistoryId": 0,
                        "ActiveInd": "Y",
                        "HabitsDescription": item.HabitsDescription,
                        "HistoryHabitsId": item.HistoryHabitsID,
                        "HabitsId": item.HabitsId
                    };
                    drugObj.DrugArray.push(newObj); 
                }
            } else {
               
                if (drugObj.DrugArray.length > 0) {
                    var statusfilter = $filter("filter")(drugObj.DrugArray, { "HistoryHabitsId": item.HistoryHabitsID }, true) || [];
                    if (statusfilter.length > 0) {
                       
                        angular.forEach(drugObj.DrugArray, function (ditem, index) {
                            if (item.HistoryHabitsID == ditem.HistoryHabitsId) {
                                if (ditem.DrugHistoryId != 0) {
                                    ditem.ActiveInd = "N";
                                } else {
                                   
                                    drugObj.DrugArray.splice(index, 1);
                                }
                            }
                        });
                    }
                }
            }
       
            var filterAllselect = $filter("filter")($scope.DrugNames, { "Ischecked": true }, true) || [];
            if (filterAllselect.length === $scope.DrugNames.length) {
                $scope.AllDrugListSelected = true;
                $scope.DrugListSelectedText = "All Selected";
            } else if (filterAllselect.length > 0) {
                if (filterAllselect.length == 1) {
                    $scope.AllDrugListSelected = false;
                    $scope.DrugListSelectedText = filterAllselect[0].HabitsDescription;
                } else {
                    $scope.AllDrugListSelected = false;
                    $scope.DrugListSelectedText = "Selected";
                }
            } else {
                $scope.AllDrugListSelected = false;
                $scope.DrugListSelectedText = "Select";
            }
         
           console.log("Final DrugArray:", JSON.stringify(drugObj.DrugArray));
        };


      


        $scope.ChangeAllDrugSelect = function (checked) {
            // 1. Get Drug Object from LifestyleHistoryArray where HistoryId = 3
            var drugObj = $scope.obj.LifestyleHistoryArray.find(function (item) {
                return item.HistoryId === 3 && item.DeleteInd == 'N';
            });

            // 2. If drugObj not found, stop the function
            if (!drugObj) return;

            // 3. If checkbox is checked
            if (checked) {
                $scope.DrugListSelectedText = "All Selected";

                // Mark all DrugNames as checked and add/update in DrugArray
                angular.forEach($scope.DrugNames, function (item) {
                    item.Ischecked = true;

                    // Check if item already exists in DrugArray
                    var existing = drugObj.DrugArray.find(function (d) {
                        return d.HistoryHabitsId === item.HistoryHabitsID;
                    });

                    if (existing) {
                        existing.ActiveInd = "Y"; // update
                    } else {
                        // Add new entry
                        var newItem = {
                            DrugHistoryId: 0,
                            ActiveInd: "Y",
                            HabitsDescription: item.HabitsDescription,
                            HistoryHabitsId: item.HistoryHabitsID,
                            HabitsId: item.HabitsId
                        };
                        drugObj.DrugArray.push(newItem);
                    }
                });

            } else {
                // 4. If checkbox is unchecked
                $scope.DrugListSelectedText = "Select";

                angular.forEach($scope.DrugNames, function (item) {
                    item.Ischecked = false;

                    // Find the existing item in DrugArray
                    var index = drugObj.DrugArray.findIndex(function (d) {
                        return d.HistoryHabitsId === item.HistoryHabitsID;
                    });

                    if (index !== -1) {
                        var existing = drugObj.DrugArray[index];

                        // If it's from DB (DrugHistoryId != 0), mark as inactive
                        if (existing.DrugHistoryId !== 0) {
                            existing.ActiveInd = "N";
                        } else {
                            // If it's not saved yet, remove from array
                            drugObj.DrugArray.splice(index, 1);
                        }
                    }
                });
            }

            console.log("Final DrugArray:", drugObj.DrugArray);
        };

        $scope.onClickClearlifestyleHistory = function (type, item) {
            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure want to clear lifestyle History data?</h4>", function () {
                if (type == 'Smoking') {
                    item.SmokingQuantityId = 0;
                    item.SmokingQuantityName = "";
                    item.SmokingStatusId = 0;
                    item.SmokingStatusName = "";
                    item.SmokingDuration = "";
                    item.SmokingDurationType = "";
                    item.SmokingDurationTypeName = "";
                    item.SmokingDurationDate = null;
                    item.SmokeShowDateFormat = false;
                    item.SmokingFromDate = "";
                    item.SmokingToDate = "";
                    item.DeleteInd = "Y";
                    $scope.obj.LifestyleHistory.Smokinglist = $scope.obj.LifestyleHistory.Smokinglist || [];
                    var count = 0;
                    angular.forEach($scope.obj.LifestyleHistory.Smokinglist, function (ditem) {
                        if (ditem.DeleteInd == 'N') {
                            count++;
                        }
                    });
                    if (count == 0) {
                        $scope.obj.LifestyleHistory.SmokingType = "";
                    }
                }
                if (type == 'Alcohol') {
                    $scope.obj.LifestyleHistory.AlcoholQuantityId = 0;
                    $scope.obj.LifestyleHistory.AlcoholQuantityName = "";
                    $scope.obj.LifestyleHistory.AlcoholStatusId = 0;
                    $scope.obj.LifestyleHistory.AlcoholStatusName = "";
                    $scope.obj.LifestyleHistory.AlcoholDuration = "";
                    $scope.obj.LifestyleHistory.AlcoholDurationType = "";
                    $scope.obj.LifestyleHistory.AlcoholDurationTypeName = "";
                    $scope.obj.LifestyleHistory.AlcoholDurationDate = "";
                    $scope.obj.LifestyleHistory.AlcoShowDateFormat = false;
                    $scope.obj.LifestyleHistory.AlcoholType = "";
                    $scope.obj.LifestyleHistory.AlcoholType = "";
                    
                }
                if (type == 'Drug') {
                    $scope.obj.LifestyleHistory.DrugQuantityId = 0;
                    $scope.obj.LifestyleHistory.DrugQuantityName = "";
                    $scope.obj.LifestyleHistory.DrugWhenQuitId = 0;
                    $scope.obj.LifestyleHistory.DrugWhenQuit = "";
                    $scope.obj.LifestyleHistory.DrugDuration = "";
                    $scope.obj.LifestyleHistory.DrugDurationType = "";
                    $scope.obj.LifestyleHistory.DrugDurationTypeName = "";
                    $scope.obj.LifestyleHistory.DrugDurationDate = "";
                    $scope.obj.LifestyleHistory.DrugArray = $scope.obj.LifestyleHistory.DrugArray || [];
                    $scope.DrugListSelectedText = "Select";
                    $scope.obj.LifestyleHistory.DrugShowDateFormat = false;
                    $scope.obj.LifestyleHistory.DrugType = "";
                    
                }
                $scope.obj.LifestyleHistory.Remarks = "";
                $scope.obj.LifestyleHistory.ShowNote = false;

                if ($scope.DrugNames.length > 0) {
                    angular.forEach($scope.DrugNames, function (item) {
                        item.Ischecked = false;
                        item.ActiveInd = 'N';
                    });
                }
                $scope.AllDrugListSelected = false;
                if ($scope.obj.LifestyleHistory.DrugArray.length > 0) {
                    var drugList = [];
                    angular.forEach($scope.obj.LifestyleHistory.DrugArray, function (ditem, index) {
                        if (ditem.DrugHistoryId != 0) {
                            ditem.ActiveInd = "N";
                            drugList.push(ditem);
                        }
                    });
                    $scope.obj.LifestyleHistory.DrugArray = angular.copy(drugList);
                }
                $scope.$digest();
            }, function () {
                r = "You pressed Cancel!";
            });
        };

        

        

