        $scope.ChangeDurationTODATE = function (item) {
            if (item.DurationType === "SB") {
                item.Duration = "";
            } else if (item.DurationType === "D" || item.DurationType === "W" || item.DurationType === "Y") {
                if (item.Duration !== "") {
                    const durationValue = parseInt(item.Duration);
                    const currentDate = new Date();
                    let pastDate = new Date(currentDate);

                    if (item.DurationType === "D") {
                        pastDate.setDate(currentDate.getDate() - durationValue);
                    } else if (item.DurationType === "W") {
                        pastDate.setDate(currentDate.getDate() - (durationValue * 7));
                    } else if (item.DurationType === "Y") {
                        pastDate.setFullYear(currentDate.getFullYear() - durationValue);
                    }

                    item.DurationDate = formatDate(pastDate);
                }
            }
        };

        function formatDate(date) {
            const month = date.getMonth() + 1;
            const day = date.getDate();
            const year = date.getFullYear();
            return `${month}-${day}-${year}`;
        }

