        $scope.SaveVitals = function (Item, id, vitalid) {
            if (Item.Value1 == '' && Item.Value2 == '') {
                alertify.error("Please Enter Values in Vitals");
                return false;
            }
            var List = $filter("filter")($scope.GetVitalsArray, function (item, index) { return item.VitalId === vitalid && item.DeleteInd == 'N'; });
            if (List.length == 4) {
                alertify.error("The Maximum limit has been Reached");
                return false;
            }
            var obj = {
                "AppointmentVitalDataId": 0,
                "VitalId": Item.VitalId || '',
                "VitalDesc": Item.VitalDesc || '',
                "Value1": "",
                "Value2": "",
                "UnitTypeId": Item.UnitTypeId || 1,
                "UnitTypeName": Item.UnitTypeName || "",
                "DeleteInd": "N",
                "OnSetDate": '',
                "OrderType": id || '',
            }
            $scope.GetVitalsArray.push(obj);
        };

        $scope.ChangeVitalUnits = function (item) {
            if (item.VitalId == 11) {
                item.UnitTypeName = item.UnitTypeId == 1 ? "°F" : "°C";
            } else if (item.VitalId == 8) {
                item.UnitTypeName = item.UnitTypeId == 3 ? "mg/dL" : "mmoL/L";
            } else if (item.VitalId == 1) {
                item.UnitTypeName = item.UnitTypeId == 5 ? "Lb" : "Kg";
            } else if (item.VitalId == 2) {
                item.UnitTypeName = item.UnitTypeId == 7 ? "In" : "CM";
            }
        };




        $scope.ShowImplantInActive = function (item) {
            if ($scope.obj.ImplantList.length > 0) {
                angular.forEach($scope.obj.ImplantList, function (xitem) {
                    xitem.ImplantDataShowInActive = false;
                });
            }
            item.ImplantDataShowInActive = !item.ImplantDataShowInActive;

        }


        $scope.ShowSigSearch = function () {
            $scope.SigSearch.Shows = !$scope.SigSearch.Shows;
        }

        $scope.RemoveVitals = function (Item, id, Vid) {
            var index = $scope.GetVitalsArray.indexOf(Item);
            if (Item.AppointmentVitalDataId == 0) {
                if (index > -1) {
                    $scope.GetVitalsArray.splice(index, 1);
                    if ($scope.GetVitalsArray.length > 0) {
                        let TempArray = $filter("filter")($scope.GetVitalsArray, { "VitalId": Vid, "DeleteInd": 'N' }, true);
                        if (TempArray.length == 0) {
                            var obj = {
                                "AppointmentVitalDataId": 0,
                                "VitalId": Item.VitalId || '',
                                "VitalDesc": Item.VitalDesc || '',
                                "Value1": "",
                                "Value2": "",
                                "UnitTypeId": Item.UnitTypeId || 1,
                                "UnitTypeName": Item.UnitTypeName || "",
                                "DeleteInd": "N",
                                "OnSetDate": '',
                                "OrderType": id || '',
                            }
                            $scope.GetVitalsArray.push(obj);
                        }
                    }
                }
            } else {
                Item.DeleteInd = "Y";
                if ($scope.GetVitalsArray.length > 0) {
                    let TempArray = $filter("filter")($scope.GetVitalsArray, { "VitalId": Vid, "DeleteInd": 'N' }, true);
                    if (TempArray.length == 0) {
                        var obj = {
                            "AppointmentVitalDataId": 0,
                            "VitalId": Item.VitalId || '',
                            "VitalDesc": Item.VitalDesc || '',
                            "Value1": "",
                            "Value2": "",
                            "UnitTypeId": Item.UnitTypeId || 1,
                            "UnitTypeName": Item.UnitTypeName || "",
                            "DeleteInd": "N",
                            "OnSetDate": '',
                            "OrderType": id || '',
                        }
                        $scope.GetVitalsArray.push(obj);
                    }
                }
            }
        };
        $scope.changeBasicQuestions = function (item, mitem) {
            var List = $filter("filter")(mitem.Answers, { "AnswerId": item }, true);
            if (List.length > 0) {
                mitem.Answer = List[0].AnswerName;
                mitem.AnswerId = List[0].AnswerId;
                mitem.Score = List[0].Score;
            } else {
                mitem.Answer = "";
            }
        }
        $scope.changeBasicSubQuestions = function (item, nitem, mitem) {
            var List = $filter("filter")(nitem.Answers, { "AnswerId": item }, true);
            if (List.length > 0) {
                nitem.Answer = List[0].AnswerName;
                nitem.Score = List[0].Score;
                let sum = 0;
                angular.forEach(mitem.SubQuestions, function (hitem) {
                    sum = sum + hitem.Score;
                    if (mitem.QuestionId == 4) {
                        $scope.ScoreObject.PHQScore = sum;
                    }
                    if (mitem.QuestionId == 7) {
                        $scope.ScoreObject.AUDITScore = sum;
                    }
                });
            } else {
                nitem.Answer = "";
            }
        }
        $scope.changeSocialQuestions = function (item, mitem) {
            var List = $filter("filter")(mitem.Answers, { "AnswerId": item }, true);
            if (List.length > 0) {
                mitem.Answer = List[0].AnswerName;
                mitem.Score = List[0].Score;
                let sum = 0;
                angular.forEach($scope.obj.PsychologicalObservationsArray, function (hitem) {
                    if (hitem.TypeId == 2) {
                        sum += hitem.Score;
                        $scope.ScoreObject.NHANESscore = sum;
                    }
                });
            } else {
                mitem.Answer = "";
            }
        }
        $scope.changeHumilationQuestions = function (item, mitem) {
            var List = $filter("filter")(mitem.Answers, { "AnswerId": item }, true);
            if (List.length > 0) {
                mitem.Answer = List[0].AnswerName;
                mitem.Score = List[0].Score;
                let sum = 0;
                angular.forEach($scope.obj.PsychologicalObservationsArray, function (hitem) {
                    if (hitem.TypeId == 3) {
                        sum = sum + hitem.Score;
                        $scope.ScoreObject.HARKscore = sum;
                    }
                });
            } else {
                mitem.Answer = "";
            }
        }


        $scope.previousSearchText = "";
        $scope.filteredMedicationList = [];

        $scope.GetDrugDataListFromRcopia = function (val) {
            if (!val || val.trim().length === 0) {
                console.log("Input is empty or cleared"); // Debugging
                $scope.previousSearchText = "";
                $scope.filteredMedicationList = [];
                return [];
            }
            var req = {
                "VendorName": "Appolo Pharmacy",
                "VendorPassword": "abc123",
                "searchText": val || "nexium",
                "RcopiaVendorAccountName": doctorinfo.doctordata.UserAddress[0].RcopiaVendorAccountName,
                "RcopiaVendorAccountPassword": doctorinfo.doctordata.UserAddress[0].RcopiaVendorAccountPassword,
                "RcopiaPracticeId": doctorinfo.doctordata.UserAddress[0].RcopiaPracticeId
            }

            if (!val || val.length < 3) {
                $scope.previousSearchText = "";
                $scope.filteredMedicationList = [];
                return [];
            }
            else {

                if ($scope.previousSearchText == "" && $scope.filteredMedicationList.length == 0) {
                    return eHnoteConditionsDataService.getDrugDetailDataFromRcopia(req).then(function (resp) {
                        resp.data.DrugDetailsList = resp.data.DrugDetailsList || [];
                        if (resp.data.DrugDetailsList !== undefined) {
                            if (resp.data.DrugDetailsList.length < 200) {
                                $scope.previousSearchText = val;
                                $scope.filteredMedicationList = resp.data.DrugDetailsList;
                                return resp.data.DrugDetailsList.map(function (item) {
                                    return item;
                                });
                            } else {
                                $scope.previousSearchText = "";
                                $scope.filteredMedicationList = [];
                                alertify.error('More Records Available ! ');
                                return resp.data.DrugDetailsList.map(function (item) {
                                    return item;
                                });
                            }
                        }
                    });
                } else {
                    if (val.toLowerCase().startsWith($scope.previousSearchText.toLowerCase()) && $scope.filteredMedicationList.length < 200) {
                        return $scope.filteredMedicationList.filter(function (item) {
                            return (
                                item.BrandName &&
                                item.BrandName.toLowerCase().includes(val.toLowerCase()) // Case-insensitive comparison
                            );
                        });
                    } else {
                        $scope.previousSearchText = "";
                        $scope.filteredMedicationList = [];
                        return eHnoteConditionsDataService.getDrugDetailDataFromRcopia(req).then(function (resp) {
                            resp.data.DrugDetailsList = resp.data.DrugDetailsList || [];
                            if (resp.data.DrugDetailsList !== undefined) {
                                if (resp.data.DrugDetailsList.length < 200) {
                                    $scope.previousSearchText = val;
                                    $scope.filteredMedicationList = resp.data.DrugDetailsList;
                                    return resp.data.DrugDetailsList.map(function (item) {
                                        return item;
                                    });
                                } else {
                                    $scope.previousSearchText = "";
                                    $scope.filteredMedicationList = [];
                                    alertify.error('More Records Available ! ');
                                    return resp.data.DrugDetailsList.map(function (item) {
                                        return item;
                                    });
                                }
                            }
                        });
                    }
                }
            }
        }
      
