        $scope.Rosnewtemplate = function () {

            let mInstanceShow = $uibModal.open({
                "templateUrl": "templates/UsNewConsultation/uibpopup/RosHistorytemplate.html",
                "backdrop": "static",
                "scope": $scope,
                "windowClass": "offcanves-right",
                "keyboard": false,
               
                "controller": function ($scope, $uibModal, $uibModalInstance) {
                    $scope.Uibclose = function () {
                        $uibModalInstance.dismiss("cancel");
                    }

                    var obj = {
                        "TypeID": 2,
                        "TypeName": "ROS",
                        "PatientId": $scope.cacheStorageItem.patientid,
                        "HospitalId": $scope.HospitalId,
                        "UserId": $scope.UserId,
                    };
                    eHnotePatientDataService.GetPreviousROSHistoryData(obj).then(function (resp) {
                        $scope.PreviousInvestigations = [];
                        if (resp.data.rows != undefined) {
                            $scope.PreviousInvestigations = resp.data.rows;
                        }
                        if ($scope.PreviousInvestigations.length > 0) {
                            $scope.loadPreviousData();
                        }
                    });
                    $scope.loadPreviousData = function () {
                        var PreviousPhyscicalevaluation = [];
                        $scope.PROSAllergyHeaders = angular.copy(GetRemarksHeaders());
                        if ($scope.PreviousInvestigations.length > 0) {
                            angular.forEach($scope.PreviousInvestigations, function (item, index) {
                                if (item.CustomAllergyRemarks != undefined) {
                                    if (item.CustomAllergyRemarks.length > 0) {
                                        item.PROSAllergyHeaders = angular.copy(GetRemarksHeaders());
                                        
                                        angular.forEach(item.CustomAllergyRemarks, function (citem, index) {
                                            angular.forEach(item.PROSAllergyHeaders, function (hitem) {
                                                var filetrarray = $filter("filter")(item.CustomAllergyRemarks, function (iterator, ind) { return iterator.CustomAllergyRemarkCategory == hitem.Name && iterator.CustomAllergyValue != ''; }) || [];
                                                if (filetrarray.length > 0) {
                                                    hitem.Active = "Y";
                                                }
                                            });
                                        });

                                    }
                                }
                                if (item.PsychologicalObservationsArray != undefined) {
                                    if (item.PsychologicalObservationsArray.length > 0) {
                                        item.ScoreObject = angular.copy($scope.GetScoreObject());
                                        angular.forEach(item.PsychologicalObservationsArray, function (Nitem) {
                                            
                                            if (Nitem.DeleteInd == 'N') {
                                                angular.forEach($scope.obj.PsychologicalObservationsArray, function (Aitem) {
                                                    if (Nitem.TypeId == 1 && Aitem.TypeId == 1) {
                                                        if (Aitem.QuestionId == 4 && Nitem.QuestionId == 4) {
                                                            angular.forEach(Nitem.SubQuestions, function (sitem) {
                                                                angular.forEach(Aitem.SubQuestions, function (asitem) {
                                                                    if (asitem.SubQuestionId == sitem.SubQuestionId) {
                                                                        
                                                                        item.ScoreObject.PHQScore += sitem.Score;
                                                                    }
                                                                });

                                                            });
                                                        }
                                                        if (Nitem.QuestionId == 7 && Aitem.QuestionId == 7) {
                                                            angular.forEach(Nitem.SubQuestions, function (sitem) {
                                                                angular.forEach(Aitem.SubQuestions, function (asitem) {
                                                                    if (asitem.SubQuestionId == sitem.SubQuestionId) {

                                                                        item.ScoreObject.AUDITScore += sitem.Score;
                                                                    }
                                                                });

                                                            });
                                                        }
                                                        if (Aitem.QuestionId == Nitem.QuestionId) {

                                                            Aitem.Score = Nitem.Score;
                                                        }
                                                    }
                                                    if (Nitem.TypeId == 2 && Aitem.TypeId == 2) {
                                                        if (Aitem.QuestionId == Nitem.QuestionId) {

                                                            item.ScoreObject.NHANESscore += Nitem.Score;
                                                        }
                                                    }
                                                    if (Nitem.TypeId == 3 && Aitem.TypeId == 3) {
                                                        if (Aitem.QuestionId == Nitem.QuestionId) {

                                                            item.ScoreObject.HARKscore += Nitem.Score;
                                                        }
                                                    }

                                                });
                                            } else {
                                                item.ScoreObject = angular.copy($scope.GetScoreObject());
                                            }
                                        });
                                    } else {
                                        item.ScoreObject = angular.copy($scope.GetScoreObject());
                                    }
                                }
                            });

                        }

                    }
                }
            });
        }

