        $scope.onisNKOHSelectedV2 = function () {
            if ($scope.obj.isNKOHSelected) {
                $scope.onisNKOHSelected();
                return;
            }
            var NKOHList = $filter("filter")($scope.obj.OccularHistoryArray, { "HistoryId": 1 }, true) || [];
            angular.forEach(NKOHList, function (item) {
                if (item.PatientDetailId === 0) {
                    var indexToRemove = $scope.obj.OccularHistoryArray.indexOf(item);
                    if (indexToRemove !== -1) {
                        $scope.obj.OccularHistoryArray.splice(indexToRemove, 1);
                    }
                } else {
                    item.DeleteInd = 'Y';
                }
            });
        };

        // v2 renders "No Known Ocular Surgical History" as a checkbox, so it can be un-set. v1 used
        // a radio, which could not, and every branch of onisNKOSHSelected is guarded by
        // isNKOSHSelected - so clearing the box there does nothing and the pseudo row stays in the
        // array with DeleteInd 'N' and still saves. Only the v2 template calls this.
        $scope.onisNKOSHSelectedV2 = function () {
            if ($scope.obj.isNKOSHSelected) {
                $scope.onisNKOSHSelected();
                return;
            }
            var NKOSHList = $filter("filter")($scope.obj.OcularSurgicalHistoryArray, { "HistoryId": 1 }, true) || [];
            angular.forEach(NKOSHList, function (item) {
                if (item.PatientDetailId === 0) {
                    var indexToRemove = $scope.obj.OcularSurgicalHistoryArray.indexOf(item);
                    if (indexToRemove !== -1) {
                        $scope.obj.OcularSurgicalHistoryArray.splice(indexToRemove, 1);
                    }
                } else {
                    item.DeleteInd = 'Y';
                }
            });
        };

