        // if (i === 0) duplicate guard, so a duplicate click leaves the chip grey while its row is
        // still in the table. Re-sync from the array afterwards. Only the v2 template calls this.
        $scope.onRosSystemicHistoryBlurChangeV2 = function (SystemicHistory) {
            $scope.onRosSystemicHistoryBlurChange(SystemicHistory);
            var HistoryId = (SystemicHistory || {}).HistoryId;
            if (HistoryId === undefined || HistoryId === '') {
                return;
            }
            var FreqList = $filter("filter")($scope.FrequentlySystemicHistory, function (fitem) {
                return fitem.HistoryId == HistoryId;
            }, true) || [];
            if (FreqList.length > 0) {
                var Rows = $filter("filter")($scope.obj.SystemicHistoryArray, function (fitem) {
                    return fitem.HistoryId == HistoryId && fitem.DeleteInd == 'N' && fitem.IsChecked;
                }, true) || [];
                FreqList[0].Onselect = Rows.length > 0;
            }
        };

