        // v2 renders "No Known Family History" as a checkbox, so it can be un-set. v1 used a radio,
        // which could not, and every branch of onisNKFHSelected is guarded by isNKFHSelected - so
        // clearing the box there does nothing and the pseudo row stays in the array with DeleteInd
        // 'N' and still saves. Only the v2 template calls this.
        $scope.onisNKFHSelectedV2 = function () {
            if ($scope.obj.isNKFHSelected) {
                $scope.onisNKFHSelected();
                return;
            }
            var NKFHList = $filter("filter")($scope.obj.FamilyHistory, { "HistoryId": 1 }, true) || [];
            angular.forEach(NKFHList, function (item) {
                if (item.PatientDetailId === 0) {
                    var indexToRemove = $scope.obj.FamilyHistory.indexOf(item);
                    if (indexToRemove !== -1) {
                        $scope.obj.FamilyHistory.splice(indexToRemove, 1);
                    }
                } else {
                    item.DeleteInd = 'Y';
                }
            });
        };

        // v2 binds the frequent chips with ng-model="freqAll.Onselect", so clicking one un-ticks it
        // before the handler runs. onRosFamilyHistoryBlurChange sets Onselect inside its
        // if (i === 0) duplicate guard, so a duplicate click leaves the chip grey while its row is
        // still in the table. Re-sync from the array afterwards. Only the v2 template calls this.
        $scope.onRosFamilyHistoryBlurChangeV2 = function (familyHistory) {
            $scope.onRosFamilyHistoryBlurChange(familyHistory);
            var HistoryId = (familyHistory || {}).HistoryId;
            if (HistoryId === undefined || HistoryId === '') {
                return;
            }
            var FreqList = $filter("filter")($scope.FrequentlyFamilyHistory, function (fitem) {
                return fitem.HistoryId == HistoryId;
            }, true) || [];
            if (FreqList.length > 0) {
                var Rows = $filter("filter")($scope.obj.FamilyHistory, function (fitem) {
                    return fitem.HistoryId == HistoryId && fitem.DeleteInd == 'N';
                }, true) || [];
                FreqList[0].Onselect = Rows.length > 0;
            }
        };

