        // v2 binds the frequent chips with ng-model="freqAll.Onselect", so clicking one un-ticks it
        // before the handler runs. onRosVaccinationHistoryBlurChange only sets Onselect inside its
        // if (i === 0) duplicate guard, so a duplicate click leaves the chip grey while its row is
        // still in the table. Re-sync from the array afterwards. Only the v2 template calls this.
        $scope.onRosVaccinationHistoryBlurChangeV2 = function (VaccinationHistory) {
            $scope.onRosVaccinationHistoryBlurChange(VaccinationHistory);
            var HistoryId = (VaccinationHistory || {}).HistoryId;
            if (HistoryId === undefined || HistoryId === '') {
                return;
            }
            var FreqList = $filter("filter")($scope.FrequentlyVaccinationStatus, function (fitem) {
                return fitem.HistoryId == HistoryId;
            }, true) || [];
            if (FreqList.length > 0) {
                var Rows = $filter("filter")($scope.obj.VaccinationHistory, function (fitem) {
                    return fitem.HistoryId == HistoryId && fitem.DeleteInd == 'N';
                }, true) || [];
                FreqList[0].Onselect = Rows.length > 0;
            }
        };

